using PCStatusBar;

int count = 0;
void Check(bool condition, string name) { if (!condition) throw new Exception(name); Console.WriteLine("PASS " + name); count++; }
StatusEvaluator Cpu() => new(new() { Yellow = 70, Red = 90, Margin = 5, RiseSeconds = 5, RecoverSeconds = 5 }, 5);
var delta = new CpuDelta();
Check(delta.Sample(10, 20, 30) == null, "CPU first sample is baseline");
Check(delta.Sample(20, 50, 50) == 80, "CPU kernel includes idle");
Check(delta.Sample(20, 50, 50) == null, "CPU zero delta");
Check(delta.Sample(0, 0, 0) == null, "CPU reset");
Check(Units.GiB(1073741824) == 1 && Units.Percent(3, 4) == 75 && Units.Percent(1, 0) == null, "GiB and coherent ratios");
var c = Cpu();
c.Update(10, 0); c.Update(95, 1); c.Update(10, 2);
Check(c.State == Severity.Green, "brief spike ignored");
c = Cpu(); c.Update(95, 0); c.Update(95, 5);
Check(c.State == Severity.Red, "direct green to red at exact duration");
c.Update(65, 6); c.Update(65, 11);
Check(c.State == Severity.Green, "direct red to green at recovery equality");
c = Cpu(); c.Update(80, 0); c.Update(95, 1); c.Update(80, 2); c.Update(95, 3); c.Update(80, 4); c.Update(95, 5);
Check(c.State == Severity.Yellow, "yellow clock independent of red oscillations");
c.Update(null, 6); Check(c.State == Severity.Unknown, "missing data neutral");
c.Update(95, 7); Check(c.State == Severity.Green, "missing data resets continuity");
c.Update(95, 20); Check(c.State == Severity.Green, "stale gap resets continuity");
c = Cpu(); c.Update(70, 0); c.Update(70, 5); Check(c.State == Severity.Yellow, "yellow equality");
c.Update(66, 6); c.Update(66, 11); Check(c.State == Severity.Yellow, "hysteresis retains yellow");
c.Update(65, 12); c.Update(65, 17); Check(c.State == Severity.Green, "yellow recovery equality");
var disk = new StatusEvaluator(new() { Yellow = 15, Red = 5, Margin = 2, Inverse = true }, 30);
Check(disk.Update(15, 0) == Severity.Yellow, "disk yellow equality");
Check(disk.Update(5, 1) == Severity.Red, "disk red equality");
Check(disk.Update(6.99, 2) == Severity.Red, "disk red hysteresis");
Check(disk.Update(7, 3) == Severity.Yellow, "disk red recovery equality");
Check(disk.Update(17, 4) == Severity.Green, "disk yellow recovery equality");
Check(disk.Update(double.NaN, 5) == Severity.Unknown, "invalid values neutral");
Check(!new Thresholds { Yellow = 10, Red = 20, Margin = 15 }.Valid(), "unreachable recovery rejected");
var previous = new Dictionary<int, ProcessSample> { [10] = new(10, 100, "python", 1), [11] = new(11, 101, "Python", 2), [12] = new(12, 102, "codex", 4), [0] = new(0, 1, "Idle", 100) };
ProcessSample[] current = [new(10, 100, "python", 3), new(11, 101, "Python", 3), new(12, 102, "codex", 5), new(0, 1, "Idle", 110)];
var usages = ProcessAccounting.Compare(previous, current, 2, 4);
Check(usages.Length == 3 && usages[0].Id == 10 && usages[0].CpuPercent == 25, "process CPU normalized to all logical processors; idle excluded");
var groups = ProcessAccounting.Group(usages);
Check(groups.Length == 2 && groups[0].Count == 2 && groups[0].CpuPercent == 37.5, "same-name processes aggregated case-insensitively");
Check(ProcessAccounting.Compare(previous, [new(10, 999, "python", 10)], 2, 4).Length == 0, "PID reuse requires new baseline");
Check(ProcessAccounting.Compare(previous, [new(99, 100, "new", 3)], 2, 4).Length == 0, "new process waits for baseline");
Check(ProcessAccounting.Compare(previous, [new(10, 100, "python", 0)], 2, 4).Length == 0, "counter reset ignored");
Check(ProcessAccounting.Compare(previous, current, 0, 4).Length == 0 && ProcessAccounting.Compare(previous, current, 2, 0).Length == 0, "invalid process denominator ignored");
Check(ProcessAccounting.Compare(previous, [new(10, 100, "python", double.NaN)], 2, 4).Length == 0, "invalid CPU times ignored");
Check(ProcessAccounting.Compare(previous, [new(10, 100, "python", 100)], 1, 4)[0].CpuPercent == 100, "single process percentage bounded");
var history = new CpuHistory();
for (int second = 0; second <= 120; second++) history.Add(second, second % 100);
Check(history.Window(120).Length == 61 && history.Window(120)[0].At == 60, "history retains actual rolling minute including boundaries");
history.Add(121, double.NaN);
Check(history.Window(121)[^1].Value == null, "invalid graph sample represented as gap");
Check(!CpuHistory.CanConnect(new(0, 20), new(10, 30), 5) && !CpuHistory.CanConnect(new(0, null), new(1, 30), 5), "graph does not bridge stale or missing samples");
Check(CpuHistory.CanConnect(new(0, 20), new(5, 30), 5), "graph accepts valid gap boundary");
history.Add(1, 50); Check(history.Window(1).Length == 1, "history resets after clock reversal");
history.Clear(); Check(history.Window(1).Length == 0, "history can reset after resume");
for (int i = 0; i < 1000; i++) history.Add(i * 0.001, 50);
Check(history.Window(1).Length == 600, "history has fixed memory bound");
var quotaNow = new DateTimeOffset(2026, 11, 3, 9, 0, 0, TimeSpan.Zero);
var quota = QuotaParsing.Codex("""{"result":{"rateLimits":{"primary":{"usedPercent":25,"windowDurationMins":10080,"resetsAt":1794301200},"secondary":null}}}""", quotaNow);
Check(quota.Windows[0].UsedPercent == 25 && quota.Windows[1].UsedPercent == null, "Codex primary weekly window does not imply a five-hour allowance");
Check(QuotaText.Window(quota, quota.Windows[0], quotaNow).Contains("75%"), "quota displays remaining rather than used percentage");
var swapped = QuotaParsing.Codex("""{"rateLimitsByLimitId":{"codex":{"primary":{"usedPercent":0,"windowDurationMins":300,"resetsAt":1793699000},"secondary":{"usedPercent":100,"windowDurationMins":10080,"resetsAt":1794301200}}}}""", quotaNow);
Check(swapped.Windows[0].UsedPercent == 100 && swapped.Windows[1].UsedPercent == 0, "quota windows identified by duration, including real zero values");
var invalidQuota = QuotaParsing.Codex("""{"rateLimits":{"primary":{"usedPercent":101,"windowDurationMins":10080,"resetsAt":-999999999999999}}}""", quotaNow);
Check(invalidQuota.Windows[0].UsedPercent == null && invalidQuota.Windows[0].ResetsAt == null, "invalid quota values and timestamps rejected");
var nullQuota = QuotaParsing.Codex("""{"rateLimits":{"primary":{"usedPercent":null,"windowDurationMins":300,"resetsAt":null},"secondary":{"usedPercent":25,"windowDurationMins":10080,"resetsAt":1794301200}}}""", quotaNow);
Check(nullQuota.Windows[1].UsedPercent == null && nullQuota.Windows[0].UsedPercent == 25, "null fields in one quota window do not hide another valid window");
var zone = TimeZoneInfo.CreateCustomTimeZone("test-msk", TimeSpan.FromHours(3), "test", "test");
var claudeQuota = QuotaParsing.ClaudeBadge(["Usage: Weekly · all models: 40%, Resets Fri 8:00 PM"], quotaNow, zone);
Check(claudeQuota.Windows[0].UsedPercent == 40 && claudeQuota.Windows[0].ResetsAt == new DateTimeOffset(2026, 11, 6, 17, 0, 0, TimeSpan.Zero), "Claude badge parses weekly value and next reset in local time");
Check(claudeQuota.Windows[1].UsedPercent == null && QuotaText.Window(claudeQuota, claudeQuota.Windows[0], quotaNow).Contains("60%"), "Claude missing short window remains unknown");
Check(QuotaParsing.ClaudeReset("Tue 12:00 AM", quotaNow, zone)?.Hour == 0 && QuotaParsing.ClaudeReset("Fri 13:00 PM", quotaNow, zone) == null, "Claude midnight and invalid clock handling");
Check(QuotaParsing.ClaudeReset("new unknown format", quotaNow, zone) == null, "unknown reset format is not guessed");
Check(QuotaText.Countdown(quotaNow.AddDays(2).AddHours(4), quotaNow) == "2 д 4 ч" && QuotaText.Countdown(quotaNow.AddHours(1).AddMinutes(7), quotaNow) == "1 ч 7 мин", "reset countdown uses days hours and minutes");
Check(QuotaText.Window(quota, quota.Windows[0], quotaNow.AddMinutes(4)).Contains("устарели"), "stale quotas are labelled explicitly");
var expiredQuota = quota with { Windows = [new("week", 90, quotaNow.AddSeconds(-1))] };
Check(QuotaText.Window(expiredQuota, expiredQuota.Windows[0], quotaNow).Contains("ожидаем") && !QuotaText.Window(expiredQuota, expiredQuota.Windows[0], quotaNow).Contains("10%"), "reset does not fabricate a new allowance");
var tags = QuotaText.Tags([quota, claudeQuota], quotaNow);
Check(tags.Length == 3 && tags[0].Provider == "Codex" && tags[0].Period == "week" && tags[1].Provider == "Claude" && tags[2].Period == "5 часов", "tag order and English provider labels with Codex short window omitted");
Check(tags[2].Value == "None" && tags[0].Value == "75%", "unknown tags use None while real values use remaining percentages");
Check(QuotaText.Tags([swapped], quotaNow).Length == 1, "Codex five-hour item stays hidden even when data exists");
var allQuotaWindows = new QuotaVisibility(true, true, true, true);
Check(QuotaText.Tags([quota, claudeQuota], quotaNow, allQuotaWindows).Length == 4, "all four quota windows can be enabled including unknown values");
Check(QuotaText.Tags([swapped], quotaNow, new(false, false, true, false)) is [{ Provider: "Codex", Period: "5 часов", Value: "100%" }], "Codex five-hour visibility is independent of weekly and Claude windows");
Check(QuotaText.Tags([quota, claudeQuota], quotaNow, new(true, false, false, false)) is [{ Provider: "Claude", Period: "5 часов", Value: "None" }], "Claude five-hour window can be selected alone without fabricated data");
Check(QuotaText.Tags([quota, claudeQuota], quotaNow, new(false, true, false, false)) is [{ Provider: "Claude", Period: "week" }], "Claude weekly visibility is independent");
Check(QuotaText.Tags([quota, claudeQuota], quotaNow, new(false, false, false, true)) is [{ Provider: "Codex", Period: "week" }], "Codex weekly visibility is independent");
var noQuotaWindows = new QuotaVisibility(false, false, false, false);
Check(!noQuotaWindows.AnyEnabled() && QuotaText.Ticker([quota, claudeQuota], quotaNow, noQuotaWindows) == "", "all quota windows can be disabled without filler text");
Check(QuotaText.Tags([quota], quotaNow.AddMinutes(4))[0] is { Value: "None", Reset: null }, "stale tags do not retain an apparent current percentage");
var overlayRect = OverlayGeometry.Calculate(new(0, 1392, 3440, 48), 560, 240, 38, 1);
Check(overlayRect == new System.Drawing.Rectangle(560, 1397, 2640, 38), "fixed overlay stays between chosen left and right taskbar margins");
var negativeOverlay = OverlayGeometry.Calculate(new(-1920, 1032, 1920, 48), 100, 200, 38, 1);
Check(negativeOverlay.Left == -1820 && negativeOverlay.Right == -200, "overlay supports negative monitor coordinates");
var constrainedOverlay = OverlayGeometry.Calculate(new(0, 0, 800, 48), 10000, 10000, 60, 1);
Check(constrainedOverlay.Left >= 0 && constrainedOverlay.Right <= 800 && constrainedOverlay.Width >= 200 && constrainedOverlay.Height <= 48, "extreme margins and height remain inside taskbar");
Check(OverlayGeometry.Calculate(new(0, 0, 3000, 72), 100, 200, 38, 1.5).Height == 57, "overlay dimensions scale with DPI");
var wideAdaptive = OverlayGeometry.Adaptive(new(0, 1392, 3440, 48), 3440, 560, 240, 38, 1, 539, 221);
Check(wideAdaptive.Left == 560 && wideAdaptive.Right == 3200, "adaptive placement preserves calibrated wide-screen region");
var narrowAdaptive = OverlayGeometry.Adaptive(new(0, 1032, 1920, 48), 3440, 560, 240, 38, 1, 539, 221);
Check(narrowAdaptive.Width < wideAdaptive.Width && narrowAdaptive.Left >= 549 && narrowAdaptive.Right <= 1689, "resolution shrink respects actual application and tray occupancy");
var crowded = OverlayGeometry.Adaptive(new(0, 1032, 1920, 48), 3440, 560, 240, 38, 1, 1000, 221);
Check(crowded.Left >= 1010 && crowded.Width < narrowAdaptive.Width, "new application buttons further reduce available region");
Check(OverlayGeometry.Adaptive(new(0, 1032, 1920, 48), 3440, 560, 240, 38, 1, 1690, 221).Width == 0, "no free gap never forces a minimum window over system buttons");
var secondScreen = OverlayGeometry.Adaptive(new(-1920, 1032, 1920, 48), 3440, 560, 240, 38, 1, 539, 221);
Check(secondScreen.Left == narrowAdaptive.Left - 1920 && secondScreen.Right == narrowAdaptive.Right - 1920, "adaptive placement preserves negative monitor origin");
var shellInsets = OverlayGeometry.OccupiedInsets(new(0, 1392, 3440, 48), [new(0,1392,55,48),new(495,1392,44,48),new(3219,1392,32,48),new(3251,1392,44,48),new(3299,1392,24,48),new(3327,1392,24,48),new(3359,1392,65,48),new(3428,1392,12,48)]);
Check(shellInsets == (539, 221, true), "taskbar button rectangles distinguish application area and right tray cluster");
Check(!OverlayGeometry.OccupiedInsets(new(0,0,1920,48), [new(0,0,55,48)]).Valid, "incomplete taskbar accessibility data is not accepted as an empty tray");
int[] naturalWidths = [400,100,80,144,200,210,210,90], compactWidths = [160,65,80,90,80,100,100,75];
bool[] allEnabled = [true,true,true,true,true,true,true,true]; int[] hideOrder = [3,0,7,1,6,5,4,2];
PanelLayout Plan(int width, bool[]? enabled = null) => ResponsiveLayout.Calculate(width,naturalWidths,compactWidths,enabled??allEnabled,hideOrder,3,8,240,24);
Check(!Plan(2640).Compact && Plan(2640).Visible.All(v => v), "wide layout preserves full text and all blocks");
Check(Plan(1140).Compact && Plan(1140).Visible.All(v => v), "medium layout uses compact text before hiding blocks");
Check(Plan(650).Visible[2] && Plan(650).Visible[4] && !Plan(650).Visible[3] && !Plan(650).Visible[0] && Plan(650).OverflowWidth > 0, "narrow layout prioritizes CPU and RAM and provides overflow access");
Check(Plan(150).ContentWidth <= 150 && Plan(150).OverflowWidth > 0, "very narrow layout keeps an overflow entry without exceeding viewport");
Check(Plan(0).ContentWidth == 0 && Plan(0).Visible.All(v => !v), "zero free space hides content without occupying protected taskbar");
bool allFit = true;
for(int width=0;width<=3000;width+=17){var p=Plan(width);int actual=p.Visible.Select((v,i)=>v?p.Widths[i]+6:0).Sum()+(p.OverflowWidth>0?p.OverflowWidth+6:0);allFit &= actual<=p.ContentWidth && p.ContentWidth<=width;}
Check(allFit, "layout invariants hold across shrinking and growing viewports");
bool[] noGpu = [true,true,true,true,true,true,true,false];
Check(!Plan(2640,noGpu).Visible[7] && Plan(2640,noGpu).OverflowWidth == 0, "disabled GPU is not treated as a missing overflow block");
Console.WriteLine($"{count} checks passed");
